export const index="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>GoldenEpics · Campaign Commerce</title><link rel=\"stylesheet\" href=\"/style.css\"><script src=\"/app.js\" defer></script></head><body><header><a href=\"/\">GoldenEpics <span>✦</span></a><span class=\"tag\">PAYPAL SANDBOX</span></header><main><section class=\"hero\"><div class=\"eyebrow\">FROM A GOOD IDEA TO A CAMPAIGN</div><h1>Your next campaign.<br><em>Ready to take shape.</em></h1><p>Bring your product. Explore an AI creative proposal. Purchase a campaign copy package through PayPal Sandbox, then collect your work in one place.</p><div class=\"steps\"><span>01 / Shape your brief</span><span>02 / Review & checkout</span><span>03 / Create & collect</span></div></section><div id=\"notice\" role=\"status\" aria-live=\"polite\"></div><div class=\"workspace\"><section class=\"panel\"><div class=\"eyebrow\">YOUR STARTING POINT</div><h2>Tell us the story.</h2><form id=\"brief\"><label>Product or brand<input name=\"product\" maxlength=\"1000\" placeholder=\"A brand worth talking about\" required></label><label>What does it help people do?<textarea name=\"description\" maxlength=\"1000\" rows=\"3\" required></textarea></label><label>Who is it for?<textarea name=\"audience\" maxlength=\"1000\" rows=\"2\" required></textarea></label><label>One thing they should do<input name=\"goal\" maxlength=\"1000\" placeholder=\"Try it, visit, sign up…\" required></label><div class=\"package\"><h3>Campaign Starter <span>$9 USD</span></h3><p>Three hooks · 30-second script · three captions · carousel outline · visual brief</p><small>Test purchase in PayPal Sandbox. Deliverables are copy and production guidance.</small></div><button type=\"submit\">Save campaign brief →</button><button id=\"sample\" type=\"button\" class=\"quiet\">Fill a sample brief</button></form></section><section class=\"panel order-panel\"><div class=\"eyebrow\">YOUR CAMPAIGN WORKSPACE</div><h2>A little progress, kept.</h2><p class=\"subtle\" id=\"connections\">Checking connections…</p><div id=\"orders\"></div></section></div><footer>GoldenEpics ✦ Keep the good ideas moving.<a href=\"https://github.com/GSpidey/goldenepics-paypal-campaign-commerce\" target=\"_blank\" rel=\"noreferrer\">Open source · MIT</a></footer></main></body></html>\n";
export const app="const $=s=>document.querySelector(s);let busy=false;\nconst el=(tag,text,cls)=>{const x=document.createElement(tag);if(text)x.textContent=text;if(cls)x.className=cls;return x;};\nfunction notice(message){$('#notice').textContent=message;}\nasync function api(path,body){const r=await fetch(path,body?{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}:{});const d=await r.json();if(!r.ok)throw new Error(d.message||'This step could not finish. Please try again.');return d;}\nasync function action(id,name){if(busy)return;busy=true;notice('Working on your campaign…');try{const order=await api('/api/orders/'+id+'/'+name,{});notice(name==='capture'?'Sandbox payment verified. Your order is ready for production.':'Your campaign is saved.');if(name==='checkout'&&order.approvalUrl)location.assign(order.approvalUrl);}catch(e){notice(e.message);}finally{busy=false;await load();}}\nfunction button(order,label,name){const b=el('button',label);b.onclick=()=>action(order.id,name);return b;}\nfunction render(order){const box=el('article',null,'order');box.append(el('h3',order.brief.product),el('div',order.state.replaceAll('_',' '),'state'),el('p',order.currency+' '+order.amount+' · Sandbox order '+order.id.slice(0,8),'subtle'));if(order.message)box.append(el('p',order.message,'subtle'));if(order.proposal){const d=el('details');d.append(el('summary','Review creative proposal'),el('pre',order.proposal.text));box.append(d);}const actions=el('div',null,'actions');if(!order.proposal)actions.append(button(order,'Prepare AI proposal','proposal'));else if(!order.paypalId)actions.append(button(order,order.createUncertain?'Reconcile saved checkout':'PayPal sandbox checkout',order.createUncertain?'reconcileCreate':'checkout'));if(order.approvalUrl&&!order.receipt){const a=el('a','Open PayPal Sandbox','button quiet');a.href=order.approvalUrl;actions.append(a,button(order,'Check payment','capture'));}if(order.receipt&&!order.delivery)actions.append(button(order,'Create campaign package','fulfill'));if(order.delivery){const a=el('a','Download campaign package','button');a.href='/api/orders/'+order.id+'/download';actions.append(a);const d=el('details');d.append(el('summary','Read delivered package'),el('pre',order.delivery.text));box.append(d);}box.append(actions);return box;}\nasync function load(){try{const d=await api('/api/workspace');$('#connections').textContent=(d.connections.ai?'Creative provider configured':'Creative provider setup pending')+' · '+(d.connections.paypal?'PayPal Sandbox configured':'PayPal Sandbox setup pending');$('#orders').replaceChildren(...(d.orders.length?d.orders.map(render):[el('p','Your saved campaigns will appear here. Start with a brief on the left.','subtle')]));}catch(e){notice(e.message);}}\n$('#brief').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;try{const brief=Object.fromEntries(new FormData(e.target));await api('/api/orders',{packageId:'starter',brief});notice('Brief saved. Prepare your proposal when ready.');await load();}catch(e){notice(e.message);}finally{busy=false;}};\n$('#sample').onclick=()=>{const sample={product:'RiseQuest',description:'A companion app that helps people turn everyday plans into manageable quests.',audience:'Busy creators who want a gentler way to plan their day.',goal:'Try one small quest today.'};for(const [key,value]of Object.entries(sample))$('#brief').elements[key].value=value;};\nif(new URL(location.href).searchParams.has('cancelled'))notice('Checkout paused. Your campaign is saved for when you return.');\nload();\n";
export const style=":root{font-family:Arial,sans-serif;color:#283b35;background:#f7f4ed}*{box-sizing:border-box}body{margin:0}header{max-width:1240px;margin:auto;padding:30px 40px;display:flex;justify-content:space-between;border-bottom:1px solid #deded3}header a{font-size:24px;font-weight:700;text-decoration:none;color:inherit}header a span{color:#bd704c}.tag,.eyebrow{font-size:11px;letter-spacing:2px;font-weight:bold}.tag{padding:9px 12px;background:#ece3d0;border-radius:30px}main{max-width:1240px;margin:auto;padding:0 40px}.hero{padding:65px 0 40px;max-width:850px}h1{font-family:Georgia,serif;font-weight:400;font-size:64px;line-height:1.08;margin:20px 0}h1 em{color:#ae6644;font-weight:400}.hero p{max-width:650px;font-size:17px;line-height:1.65;color:#62706a}.steps{display:flex;gap:35px;font-size:12px;margin-top:30px}.workspace{display:grid;grid-template-columns:380px 1fr;gap:25px;margin-top:25px}.panel{border:1px solid #dadcd2;background:#fffdf7;border-radius:18px;padding:28px}h2{font:32px Georgia,serif;margin:14px 0 24px}label{display:block;font-size:12px;font-weight:bold;margin-top:20px}input,textarea{font:14px Arial;width:100%;padding:12px;border:1px solid #cdd3c9;border-radius:8px;margin-top:8px;background:#fff}button,.button{border:0;border-radius:9px;background:#2b483d;color:white;padding:13px 18px;font-weight:bold;cursor:pointer;text-decoration:none;display:inline-block;font-size:13px}button:disabled{opacity:.6;cursor:wait}form button{width:100%;margin-top:15px}.quiet{color:#31483d;background:#e9eddf}.package{background:#f0eddf;padding:16px;border-radius:12px;margin-top:24px}.package h3{font-size:14px}.package h3 span{float:right}.package p,.package small{font-size:12px;line-height:1.6}.order{border-top:1px solid #e0e1d7;padding:22px 0}.order h3{margin:0 0 12px}.state{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#89613c}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}pre{font-family:Arial;font-size:14px;white-space:pre-wrap;line-height:1.65;background:#f2f3ea;border-radius:10px;padding:16px;overflow-wrap:anywhere}.subtle{font-size:13px;line-height:1.6;color:#6b746a}details{margin-top:15px}summary{cursor:pointer}#notice:not(:empty){background:#f2e6cc;padding:15px;border-radius:10px}footer{padding:40px 0;display:flex;justify-content:space-between;color:#6a756b;font-size:12px}footer a{color:inherit}button:focus-visible,a:focus-visible{outline:3px solid #bb7956;outline-offset:3px}@media(max-width:800px){main,header{padding-left:20px;padding-right:20px}.workspace{grid-template-columns:1fr}h1{font-size:44px}.steps{gap:15px;flex-wrap:wrap}.hero{padding-top:40px}}\n";
export const setup="<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Campaign Commerce · Secure setup</title><link rel=\"stylesheet\" href=\"/style.css\"><main><h1>Connect PayPal Sandbox</h1><p>Connect the test merchant for Campaign Commerce.</p><form autocomplete=\"off\"><label>Setup token<input name=\"token\" type=\"password\" required></label><label>Sandbox client ID<input name=\"clientId\" type=\"password\" required></label><label>Sandbox client secret<input name=\"clientSecret\" type=\"password\" required></label><button>Connect sandbox</button></form><output aria-live=\"polite\"></output></main><script src=\"/setup.js\"></script></html>\n";
